import{_ as t,H as d,f as r,i as o}from"./chunks/framework.CBmkDW73.js";const _=JSON.parse('{"title":"规范评审员关卡 (Spec Reviewers)","description":"","frontmatter":{},"headers":[],"relativePath":"zh/skills/reviewers.md","filePath":"zh/skills/reviewers.md"}'),a={name:"zh/skills/reviewers.md"};function s(i,e,c,l,n,h){return d(),r("div",null,[...e[0]||(e[0]=[o('<h1 id="规范评审员关卡-spec-reviewers" tabindex="-1">规范评审员关卡 (Spec Reviewers) <a class="header-anchor" href="#规范评审员关卡-spec-reviewers" aria-label="Permalink to &quot;规范评审员关卡 (Spec Reviewers)&quot;">​</a></h1><p>规范评审员协议 (<code>skills/references/reviewers.md</code>) 规定了在 <code>design</code> 阶段提交给 <code>plan</code> 之前执行的并行评审关卡。</p><h2 id="触发式匹配机制" tabindex="-1">触发式匹配机制 <a class="header-anchor" href="#触发式匹配机制" aria-label="Permalink to &quot;触发式匹配机制&quot;">​</a></h2><p>根据规范特征动态选择评审员：</p><table tabindex="0"><thead><tr><th>触发条件</th><th>派发的评审员</th><th>审查职责</th></tr></thead><tbody><tr><td>始终触发（基线）</td><td><code>spec-compliance</code></td><td>验证契约完整性、明确的测试标准及非叙事性声明格式。</td></tr><tr><td>状态迁移 / 异步流程</td><td><code>state-machine</code></td><td>检查状态机完整性、非法状态迁移、超时及竞态条件。</td></tr><tr><td>跨规则 / 多项规范</td><td><code>cross-rule</code></td><td>验证系统规则、现有规范及项目不变量之间的一致性。</td></tr><tr><td>跨模块 / 跨仓库</td><td><code>cross-module</code></td><td>验证契约边界、Schema 兼容性及依赖关系顺序。</td></tr><tr><td>崩溃 / 恢复 / 持久化</td><td><code>safety</code></td><td>检查崩溃恢复、防数据丢失、幂等重试及回滚安全性。</td></tr><tr><td>实现复杂度较高</td><td><code>implementability</code></td><td>评估任务能否在预估范围内清晰执行，是否存在隐式歧义。</td></tr></tbody></table><h2 id="并行执行与-coordinator-批判性合成" tabindex="-1">并行执行与 Coordinator 批判性合成 <a class="header-anchor" href="#并行执行与-coordinator-批判性合成" aria-label="Permalink to &quot;并行执行与 Coordinator 批判性合成&quot;">​</a></h2><ol><li><strong>并行派发</strong>：所有被触发的评审员作为独立子智能体（Subagent）并行运行。</li><li><strong>Coordinator 合成</strong>：主智能体对其意见进行批判性评估，解决冲突、补齐遗漏、判定严重程度，并一次性修正规范。评审员提供建议，Coordinator 做出裁决。</li></ol>',7)])])}const m=t(a,[["render",s]]);export{_ as __pageData,m as default};
